CREATE TABLE inventory (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  char_id NUMBER(11) DEFAULT 0,
  nameid NUMBER(10) DEFAULT 0,
  amount NUMBER(11) DEFAULT 0,
  equip NUMBER(11) DEFAULT 0,
  identify NUMBER(6) DEFAULT 0,
  refine NUMBER(3) DEFAULT 0,
  attribute NUMBER(4) DEFAULT 0,
  card0 NUMBER(10) DEFAULT 0,
  card1 NUMBER(10) DEFAULT 0,
  card2 NUMBER(10) DEFAULT 0,
  card3 NUMBER(10) DEFAULT 0,
  option_id0 NUMBER(5) DEFAULT 0,
  option_val0 NUMBER(5) DEFAULT 0,
  option_parm0 NUMBER(3) DEFAULT 0,
  option_id1 NUMBER(5) DEFAULT 0,
  option_val1 NUMBER(5) DEFAULT 0,
  option_parm1 NUMBER(3) DEFAULT 0,
  option_id2 NUMBER(5) DEFAULT 0,
  option_val2 NUMBER(5) DEFAULT 0,
  option_parm2 NUMBER(3) DEFAULT 0,
  option_id3 NUMBER(5) DEFAULT 0,
  option_val3 NUMBER(5) DEFAULT 0,
  option_parm3 NUMBER(3) DEFAULT 0,
  option_id4 NUMBER(5) DEFAULT 0,
  option_val4 NUMBER(5) DEFAULT 0,
  option_parm4 NUMBER(3) DEFAULT 0,
  expire_time NUMBER(11) DEFAULT 0,
  favorite NUMBER(3) DEFAULT 0,
  bound NUMBER(3) DEFAULT 0,
  unique_id NUMBER(20) DEFAULT 0,
  equip_switch NUMBER(11) DEFAULT 0,
  enchantgrade NUMBER(3) DEFAULT 0
);



